// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	working := append([]rune(nil), val...)
	contentLines, closingLine := collectHeredocLines(working)

	markerLen := len(marker)
	paddingToStrip := closingLine
	closingLen := len(closingLine)
	if closingLen >= markerLen {
		paddingToStrip = closingLine[:closingLen-markerLen]
	}

	padLen := len(paddingToStrip)
	heredocStartLine := l.line
	nContent := len(contentLines)
	if nContent == 0 {
		return []rune{}, nil
	}

	var out string
	for lineNum, lineText := range contentLines {
		// find an exact match for the padding
		lineLen := len(lineText)
		index := -1

		if padLen == 0 {
			index = 0
		} else if lineLen < padLen {
			index = strings.Index(lineText, paddingToStrip)
		} else {
			samePrefix := true
			for i := 0; i < padLen && samePrefix; i++ {
				samePrefix = lineText[i] == paddingToStrip[i]
			}
			if samePrefix {
				index = 0
			} else {
				index = strings.Index(lineText, paddingToStrip)
			}
		}

		if index != 0 {
			lineNo := heredocStartLine + lineNum + 1
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, lineNo, lineText, paddingToStrip)
		}

		rest := lineText[padLen:]
		strippedLen := len(rest)
		if strippedLen == 0 {
			out += "\n"
			continue
		}

		var cleaned strings.Builder
		cleaned.Grow(len(rest))
		atContentStart := true
		for _, ch := range rest {
			if ch == '\r' {
				continue
			}
			if atContentStart && unicode.IsSpace(ch) {
				cleaned.WriteRune(ch)
				continue
			}
			atContentStart = false
			cleaned.WriteRune(ch)
		}
		copied := cleaned.String()
		out += copied + "\n"
	}

	finalText := out
	if len(finalText) > 0 && finalText[len(finalText)-1] == '\n' {
		finalText = finalText[:len(finalText)-1]
	}

	return []rune(finalText), nil
}

func (t Token) Quoted() bool {
	return t.wasQuoted > 0
}

// NumLineBreaks counts how many line breaks are in the token text.
func (t Token) NumLineBreaks() int {
	lineBreaks := strings.Count(t.Text, "\n")
	if t.wasQuoted == '<' {
		// heredocs have an extra linebreak because the opening
		// delimiter is on its own line and is not included in the
		// token Text itself, and the trailing newline is removed.
		lineBreaks += 2
	}
	return lineBreaks
}

var heredocMarkerRegexp = regexp.MustCompile("^[A-Za-z0-9_-]+$")

// isNextOnNewLine tests whether t2 is on a different line from t1
func isNextOnNewLine(t1, t2 Token) bool {
	// If the second token is from a different file,
	// we can assume it's from a different line
	if t1.File != t2.File {
		return true
	}

	// If the second token is from a different import chain,
	// we can assume it's from a different line
	if len(t1.imports) != len(t2.imports) {
		return true
	}
	for i, im := range t1.imports {
		if im != t2.imports[i] {
			return true
		}
	}

	// If the first token (incl line breaks) ends
	// on a line earlier than the next token,
	// then the second token is on a new line
	return t1.Line+t1.NumLineBreaks() < t2.Line
}

